const [h, w] = readLine().trim().split(/\s+/).map(Number);
const g = [];
for (let i = 0; i < h; i++) g.push(readLine().trim());
const dist = Array.from({ length: h }, () => new Array(w).fill(-1));
const qi = [], qj = [];
for (let i = 0; i < h; i++) for (let j = 0; j < w; j++) {
  if (g[i][j] === 'S') { dist[i][j] = 0; qi.push(i); qj.push(j); }
}
let head = 0, ans = -1;
const DI = [1, -1, 0, 0], DJ = [0, 0, 1, -1];
while (head < qi.length) {
  const i = qi[head], j = qj[head]; head++;
  if (g[i][j] === 'T') { ans = dist[i][j]; break; }
  for (let d = 0; d < 4; d++) {
    const a = i + DI[d], b = j + DJ[d];
    if (a >= 0 && a < h && b >= 0 && b < w && g[a][b] !== '#' && dist[a][b] === -1) {
      dist[a][b] = dist[i][j] + 1;
      qi.push(a); qj.push(b);
    }
  }
}
console.log(ans);

