import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int h = sc.nextInt(), w = sc.nextInt();
        String[] g = new String[h];
        for (int i = 0; i < h; i++) g[i] = sc.next();
        int[][] dist = new int[h][w];
        for (int[] r : dist) Arrays.fill(r, -1);
        ArrayDeque<int[]> q = new ArrayDeque<>();
        for (int i = 0; i < h; i++)
            for (int j = 0; j < w; j++)
                if (g[i].charAt(j) == 'S') { dist[i][j] = 0; q.add(new int[]{i, j}); }
        int[] di = {1, -1, 0, 0}, dj = {0, 0, 1, -1};
        int ans = -1;
        while (!q.isEmpty()) {
            int[] c = q.poll();
            int i = c[0], j = c[1];
            if (g[i].charAt(j) == 'T') { ans = dist[i][j]; break; }
            for (int d = 0; d < 4; d++) {
                int a = i + di[d], b = j + dj[d];
                if (a >= 0 && a < h && b >= 0 && b < w && g[a].charAt(b) != '#' && dist[a][b] == -1) {
                    dist[a][b] = dist[i][j] + 1;
                    q.add(new int[]{a, b});
                }
            }
        }
        System.out.println(ans);
    }
}

