#include <bits/stdc++.h>
using namespace std;
int main() {
    int h, w;
    cin >> h >> w;
    vector<string> g(h);
    for (auto &r : g) cin >> r;
    vector<vector<int>> dist(h, vector<int>(w, -1));
    queue<pair<int,int>> q;
    for (int i = 0; i < h; i++)
        for (int j = 0; j < w; j++)
            if (g[i][j] == 'S') { dist[i][j] = 0; q.push({i, j}); }
    int di[4] = {1, -1, 0, 0}, dj[4] = {0, 0, 1, -1};
    int ans = -1;
    while (!q.empty()) {
        auto [i, j] = q.front();
        q.pop();
        if (g[i][j] == 'T') { ans = dist[i][j]; break; }
        for (int d = 0; d < 4; d++) {
            int a = i + di[d], b = j + dj[d];
            if (a >= 0 && a < h && b >= 0 && b < w && g[a][b] != '#' && dist[a][b] == -1) {
                dist[a][b] = dist[i][j] + 1;
                q.push({a, b});
            }
        }
    }
    cout << ans << "\n";
    return 0;
}
